      INTEGER FUNCTION MPR*2(E,LMAX,LMIN)
	INTEGER*2 E,RND,LMAX,LMIN,IDV,MAXT,IS2,MAXB
      REAL*4 DV,A
C
      INTEGER*2 MHV,IDM
      REAL*4 XD
      COMMON/BAKER/MHV(360,2),IDM(3,2),XD
C
	INTEGER*2 IX,IDUM,YJD
	COMMON/CHARLY/IX(1440,2),IDUM,YJD
C
C*** FIND SUM OF AVERAGE SUCCESSIVE DIFFERENCE OF POINTS BEFORE
C    AND AFTER POINTS USED FOR K
	IDV=32767
	DV=9999.0
      MAXT=0
      IF((LMAX-1).LE.0)GOTO 40
      IF(IX(LMAX-1,E).EQ.IDV)GOTO 40
      MAXT=IABS(IX(LMAX-1,E)-IX(LMAX,E))
   40 IS2=0
      IF((LMAX+1).GT.1440)GOTO 42
      IF(IX(LMAX+1,E).EQ.IDV)GOTO 42
      IS2=IABS(IX(LMAX+1,E)-IX(LMAX,E))
   42 MAXT=(MAXT+IS2)/2
   43 MAXB=0
      IF((LMIN-1).LE.0)GOTO 44
      IF(IX(LMIN-1,E).EQ.IDV)GOTO 44
      MAXB=IABS(IX(LMIN-1,E)-IX(LMIN,E))
   44 IS2=0
      IF((LMIN+1).GT.1440)GOTO 46
      IF(IX(LMIN+1,E).EQ.IDV)GOTO 46
      IS2=IABS(IX(LMIN+1,E)-IX(LMIN,E))
   46 MAXB=(MAXB+IS2)/2
   47 A=(MAXT+MAXB)*0.1
      IF(E.EQ.2)A=A*XD
	IF(A.GT.DV .OR. A.LT.0)A=DV
C *** THE MPR VAL IS MADE NEG IN KTAB IF THE D COMPONENT IS USED FOR
C     K.  A NEG ZERO IS ZERO SO SET ALL ZEROS TO ONE
      MPR=RND(A)
      IF(MPR.EQ.0)MPR=1
      RETURN
      END
